import { createHash } from 'node:crypto'

/**
 * Tool description pinning (PLAN-V2 §11).
 *
 * An MCP server can change what a tool claims to do at any time, and the model
 * acts on that description. A server that ships a benign `search` tool, waits
 * for approval, then rewrites its description to instruct exfiltration is the
 * documented attack — nothing about the tool's *name* changed, so nothing looks
 * different.
 *
 * So the approved unit is the full behavioural surface — name, description and
 * input schema — hashed. Any drift quarantines the tool until a human re-reads
 * and re-approves it. This is a trust-on-first-use model: it cannot tell you a
 * tool was malicious from the start, only that it changed after you agreed.
 */

export interface ToolDescriptor {
  name: string
  description?: string | undefined
  inputSchema?: unknown
}

export type ToolStatus = 'approved' | 'unapproved' | 'changed'

export interface PinnedTool {
  serverId: string
  name: string
  hash: string
  approvedAt: number
}

/**
 * Hashes what the model actually sees.
 *
 * The schema is canonicalised by sorting keys, so a server reserialising its
 * JSON in a different order does not read as a behavioural change and train
 * people to click through real ones.
 */
export function hashTool(tool: ToolDescriptor): string {
  const canonical = JSON.stringify({
    name: tool.name,
    description: tool.description ?? '',
    inputSchema: canonicalise(tool.inputSchema),
  })
  return createHash('sha256').update(canonical).digest('hex').slice(0, 32)
}

function canonicalise(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(canonicalise)
  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>)
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([k, v]) => [k, canonicalise(v)]),
    )
  }
  return value
}

export class ToolApprovals {
  private readonly pinned = new Map<string, PinnedTool>()

  constructor(initial: PinnedTool[] = []) {
    for (const pin of initial) this.pinned.set(key(pin.serverId, pin.name), pin)
  }

  status(serverId: string, tool: ToolDescriptor): ToolStatus {
    const pin = this.pinned.get(key(serverId, tool.name))
    if (!pin) return 'unapproved'
    return pin.hash === hashTool(tool) ? 'approved' : 'changed'
  }

  approve(serverId: string, tool: ToolDescriptor): PinnedTool {
    const pin: PinnedTool = {
      serverId,
      name: tool.name,
      hash: hashTool(tool),
      approvedAt: Date.now(),
    }
    this.pinned.set(key(serverId, tool.name), pin)
    return pin
  }

  revoke(serverId: string, name: string): void {
    this.pinned.delete(key(serverId, name))
  }

  /** Serialisable, so approvals survive a restart. */
  export(): PinnedTool[] {
    return [...this.pinned.values()]
  }

  /**
   * Splits a server's tool list by what the user has actually agreed to.
   *
   * `changed` is kept separate from `unapproved` on purpose: a tool that
   * changed under an existing approval is a stronger signal than one never
   * seen, and deserves different words in the UI.
   */
  partition(
    serverId: string,
    tools: ToolDescriptor[],
  ): { approved: ToolDescriptor[]; unapproved: ToolDescriptor[]; changed: ToolDescriptor[] } {
    const approved: ToolDescriptor[] = []
    const unapproved: ToolDescriptor[] = []
    const changed: ToolDescriptor[] = []

    for (const tool of tools) {
      const status = this.status(serverId, tool)
      if (status === 'approved') approved.push(tool)
      else if (status === 'changed') changed.push(tool)
      else unapproved.push(tool)
    }

    return { approved, unapproved, changed }
  }
}

function key(serverId: string, name: string): string {
  return `${serverId}�${name}`
}
